-- Phase 3: customer accounts, contacts, assets and asset history.
-- Hand-written sections are marked "Hand-written"; the rest is generated by Prisma.

-- Hand-written: human-readable identifiers come from sequences, so they are unique,
-- never reused and safe under concurrent inserts. The number widens past six digits
-- instead of being cut off (lpad on its own truncates, which would create duplicates).
CREATE SEQUENCE "customer_account_number_seq";
CREATE SEQUENCE "asset_tag_seq";

CREATE FUNCTION next_customer_account_number() RETURNS text LANGUAGE sql VOLATILE AS $$
  SELECT 'CU-' || lpad(n::text, greatest(6, length(n::text)), '0')
  FROM (SELECT nextval('customer_account_number_seq') AS n) s
$$;

CREATE FUNCTION next_asset_tag() RETURNS text LANGUAGE sql VOLATILE AS $$
  SELECT 'DF-' || to_char(now() AT TIME ZONE 'UTC', 'YYYY') || '-' || lpad(n::text, greatest(6, length(n::text)), '0')
  FROM (SELECT nextval('asset_tag_seq') AS n) s
$$;

