-- CreateEnum
CREATE TYPE "AssetStatus" AS ENUM ('IN_STOCK', 'ACTIVE', 'IN_REPAIR', 'REFURBISHING', 'RETIRED', 'DISPOSED');

-- CreateEnum
CREATE TYPE "AssetEventType" AS ENUM ('REGISTERED', 'DETAILS_UPDATED', 'STATUS_CHANGED', 'CUSTOMER_CHANGED');

