-- Hand-written: constraints Prisma cannot express.

-- A user is linked to a customer account if and only if they are a customer.
ALTER TABLE "users" ADD CONSTRAINT "users_customer_account_chk"
  CHECK (("role" = 'CUSTOMER') = ("customer_account_id" IS NOT NULL));

-- At most one primary contact per customer account.
CREATE UNIQUE INDEX "customer_contacts_one_primary_idx"
  ON "customer_contacts" ("customer_account_id") WHERE "is_primary";

-- Serial uniqueness depends on normalised values, so the normalisation is enforced
-- here too: no code path can store "abc 123" next to "ABC123". The API derives
-- manufacturer_key from manufacturer (trimmed, upper case); the check only requires
-- upper case, because JavaScript and PostgreSQL upper-case a few non-ASCII letters
-- differently and an exact comparison would reject valid names.
ALTER TABLE "assets" ADD CONSTRAINT "assets_manufacturer_key_chk"
  CHECK ("manufacturer_key" = upper("manufacturer_key") AND "manufacturer_key" <> '');
ALTER TABLE "assets" ADD CONSTRAINT "assets_serial_normalised_chk"
  CHECK ("serial_number" IS NULL OR ("serial_number" = upper("serial_number") AND "serial_number" ~ '^[^[:space:]]+$'));

-- An asset in use (ACTIVE) always belongs to a customer.
ALTER TABLE "assets" ADD CONSTRAINT "assets_active_has_customer_chk"
  CHECK ("status" <> 'ACTIVE' OR "customer_account_id" IS NOT NULL);

-- A warranty cannot expire before the device was bought.
ALTER TABLE "assets" ADD CONSTRAINT "assets_warranty_after_purchase_chk"
  CHECK ("warranty_expires_on" IS NULL OR "purchase_date" IS NULL OR "warranty_expires_on" >= "purchase_date");

-- Asset history is append-only, like the audit log.
CREATE FUNCTION "asset_events_block_mutation"() RETURNS trigger AS $$
BEGIN
  RAISE EXCEPTION 'asset_events is append-only';
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER "asset_events_no_update_delete"
  BEFORE UPDATE OR DELETE ON "asset_events"
  FOR EACH ROW EXECUTE FUNCTION "asset_events_block_mutation"();
